    /// <summary>
    /// Commands accepted by the Control register.
    /// </summary>
    [Flags]
    public enum ControlFlags : byte
    {
        /// <summary>
        /// Specifies that no flags are defined.
        /// </summary>
        None = 0x0,

        /// <summary>
        /// Turn the motor torque on. The gate holds its position.
        /// </summary>
        [Description("Turn the motor torque on. The gate holds its position.")]
        EnableMotor = 0x1,

        /// <summary>
        /// Turn the motor torque off. The gate can be moved by hand.
        /// </summary>
        [Description("Turn the motor torque off. The gate can be moved by hand.")]
        DisableMotor = 0x2,

        /// <summary>
        /// Stop the current movement and hold the position.
        /// </summary>
        [Description("Stop the current movement and hold the position.")]
        Stop = 0x4,

        /// <summary>
        /// Move the gate to the lower end stop and record it as home.
        /// </summary>
        [Description("Move the gate to the lower end stop and record it as home.")]
        Calibrate = 0x8,

        /// <summary>
        /// Start sending Position events.
        /// </summary>
        [Description("Start sending Position events.")]
        EnablePositionEvent = 0x10,

        /// <summary>
        /// Stop sending Position events.
        /// </summary>
        [Description("Stop sending Position events.")]
        DisablePositionEvent = 0x20,

        /// <summary>
        /// Start sending ServoTelemetry events.
        /// </summary>
        [Description("Start sending ServoTelemetry events.")]
        EnableTelemetryEvent = 0x40,

        /// <summary>
        /// Stop sending ServoTelemetry events.
        /// </summary>
        [Description("Stop sending ServoTelemetry events.")]
        DisableTelemetryEvent = 0x80
    }

    /// <summary>
    /// Enumerates the states of the gate motor.
    /// </summary>
    public enum MotorStatus : byte
    {
        /// <summary>
        /// The motor is off. The gate refuses to move until the motor is enabled.
        /// </summary>
        [Description("The motor is off. The gate refuses to move until the motor is enabled.")]
        Disabled = 0,

        /// <summary>
        /// The motor is on and holds the gate.
        /// </summary>
        [Description("The motor is on and holds the gate.")]
        Enabled = 1
    }

    /// <summary>
    /// Enumerates the possible states of the gate.
    /// </summary>
    public enum GateStatus : byte
    {
        /// <summary>
        /// The gate is stationary and not at a known end stop.
        /// </summary>
        [Description("The gate is stationary and not at a known end stop.")]
        Idle = 0,

        /// <summary>
        /// The gate is fully raised up.
        /// </summary>
        [Description("The gate is fully raised up.")]
        Up = 1,

        /// <summary>
        /// The gate is fully lowered down.
        /// </summary>
        [Description("The gate is fully lowered down.")]
        Down = 2,

        /// <summary>
        /// The gate is moving towards a target position.
        /// </summary>
        [Description("The gate is moving towards a target position.")]
        Moving = 3,

        /// <summary>
        /// The gate is moving to the lower end stop to find home.
        /// </summary>
        [Description("The gate is moving to the lower end stop to find home.")]
        Calibrating = 4,

        /// <summary>
        /// The last movement or calibration failed.
        /// </summary>
        [Description("The last movement or calibration failed.")]
        Error = 255
    }

    internal static partial class PayloadMarshal
    {
        internal static T[] GetSubArray<T>(T[] array, int offset, int count)
        {
            var result = new T[count];
            Array.Copy(array, offset, result, 0, count);
            return result;
        }

        internal static byte ReadByte(byte[] array, int offset) => array[offset];

        internal static sbyte ReadSByte(byte[] array, int offset) => (sbyte)array[offset];

        internal static ushort ReadUInt16(byte[] array, int offset) => BitConverter.ToUInt16(array, offset);

        internal static short ReadInt16(byte[] array, int offset) => BitConverter.ToInt16(array, offset);

        internal static uint ReadUInt32(byte[] array, int offset) => BitConverter.ToUInt32(array, offset);

        internal static int ReadInt32(byte[] array, int offset) => BitConverter.ToInt32(array, offset);

        internal static ulong ReadUInt64(byte[] array, int offset) => BitConverter.ToUInt64(array, offset);

        internal static long ReadInt64(byte[] array, int offset) => BitConverter.ToInt64(array, offset);

        internal static float ReadSingle(byte[] array, int offset) => BitConverter.ToSingle(array, offset);

        internal static string ReadUtf8String(byte[] array, int offset, int count)
        {
            var length = Array.IndexOf(array, (byte)0, offset, count) - offset;
            return System.Text.Encoding.UTF8.GetString(array, offset, length < 0 ? count : length);
        }

        internal static void Write(byte[] array, int offset, byte value) => array[offset] = value;

        internal static void Write(byte[] array, int offset, sbyte value) => array[offset] = (byte)value;

        internal static void Write(byte[] array, int offset, ushort value)
        {
            array[offset] = (byte)value;
            array[offset + 1] = (byte)(value >> 8);
        }

        internal static void Write(byte[] array, int offset, short value)
        {
            array[offset] = (byte)value;
            array[offset + 1] = (byte)(value >> 8);
        }

        internal static void Write(byte[] array, int offset, uint value)
        {
            array[offset] = (byte)value;
            array[offset + 1] = (byte)(value >> 8);
            array[offset + 2] = (byte)(value >> 16);
            array[offset + 3] = (byte)(value >> 24);
        }

        internal static void Write(byte[] array, int offset, int value)
        {
            array[offset] = (byte)value;
            array[offset + 1] = (byte)(value >> 8);
            array[offset + 2] = (byte)(value >> 16);
            array[offset + 3] = (byte)(value >> 24);
        }

        internal static void Write(byte[] array, int offset, ulong value)
        {
            array[offset] = (byte)value;
            array[offset + 1] = (byte)(value >> 8);
            array[offset + 2] = (byte)(value >> 16);
            array[offset + 3] = (byte)(value >> 24);
            array[offset + 4] = (byte)(value >> 32);
            array[offset + 5] = (byte)(value >> 40);
            array[offset + 6] = (byte)(value >> 48);
            array[offset + 7] = (byte)(value >> 56);
        }

        internal static void Write(byte[] array, int offset, long value)
        {
            array[offset] = (byte)value;
            array[offset + 1] = (byte)(value >> 8);
            array[offset + 2] = (byte)(value >> 16);
            array[offset + 3] = (byte)(value >> 24);
            array[offset + 4] = (byte)(value >> 32);
            array[offset + 5] = (byte)(value >> 40);
            array[offset + 6] = (byte)(value >> 48);
            array[offset + 7] = (byte)(value >> 56);
        }

        internal static unsafe void Write(byte[] array, int offset, float value) => Write(array, offset, *(int*)&value);

        internal static void Write(byte[] array, int offset, int count, string value) =>
            System.Text.Encoding.UTF8.GetBytes(value, 0, Math.Min(value.Length, count), array, offset);

        internal static void Write<T>(byte[] array, int offset, int count, T[] values) where T : unmanaged
        {
            Buffer.BlockCopy(values, 0, array, offset, count);
        }

        internal static void Write<T>(T[] array, int offset, int count, T[] values)
        {
            Array.Copy(values, 0, array, offset, count);
        }
    }
}
